// <auto-generated/>
using BCP_BL.Models;
using BCP_BL.PublicServices.Implementation;
using BCP_BL.PublicServices.Interface;
using Microsoft.AspNetCore.Components;

namespace BCP_Frontend.Components.Pages.Public_Portal
{
    public partial class Index
    {
        [Inject]
        private IProvinceService ProvinceService { get; set; } = default!;

        [Inject]
        private ICityService CityService { get; set; } = default!;

        [Inject]
        private NavigationManager Navigation { get; set; } = default!;

        private List<GetAllProvinceResponse> Provinces = new();
        private List<GetAllCityResponse> AvailableCities = new();

        private Guid? SelectedProvinceId { get; set; }

        private Guid? SelectedCityId { get; set; }

        private string SelectedBloodGroup { get; set; } = "";

        private string SelectedComponent { get; set; } = "whole";


        protected override async Task OnInitializedAsync()
        {
            Provinces = await ProvinceService.GetAllAsync();
        }


        private async Task OnProvinceChanged(Guid? provinceId)
        {
            SelectedProvinceId = provinceId;

            SelectedCityId = null;
            AvailableCities.Clear();

            if (provinceId.HasValue)
            {
                AvailableCities =
                    await CityService.GetByProvinceIdAsync(provinceId.Value);
            }
        }

        private void HandleSearch()
        {
            var query =
                $"search-stock?provinceId={SelectedProvinceId}" +
                $"&cityId={SelectedCityId}" +
                $"&group={Uri.EscapeDataString(SelectedBloodGroup)}" +
                $"&component={Uri.EscapeDataString(SelectedComponent)}";

            Navigation.NavigateTo(query);
        }
    }
}
